out = io.StringIO()
for category, items in faqs.items():
    out.write(f'                <h3 className=\"font-roobert font-bold text-macvbet-red uppercase tracking-wider text-sm mt-8 mb-4 px-2\">{category}</h3>\\n')
    for q, a in items:
        # escape quotes
        q = q.replace('\"', '&quot;')
        a = a.replace('\"', '&quot;')
        out.write(f'                <Accordion \n')
        out.write(f'                  question=\"{q}\" \n')
        out.write(f'                  answer=\"{a}\" \n')
        out.write(f'                />\n')

with open('faq_out.txt', 'w', encoding='utf-8') as f:
    f.write(out.getvalue())
